        id: "cfaq-q3",
        lessonId: "cfaq-p11",
        statement:
          "Releia o trecho: 'O diretor, ao perceber que alguém, mesmo inepto, se dispunha a fazer o jornal para ele, praticamente de graça, topou.' A palavra 'alguém' classifica-se como:",
