        lessonId: "cfaq-p13",
        statement:
          "Qual das seguintes análises de PREPOSIÇÃO está CORRETA? (Refere-se ao trecho: 'Assistiu, sentado e escrevendo, ao desfile de 11 presidentes da República...')",
        options: [
          "'De' em 'de longe' e 'de coração arfante' são preposições que introduzem adjuntos adverbiais de modo; 'de' em 'de 11 presidentes' é preposição de complemento nominal.",
          "'A' em 'a braço' é preposição que rege objeto indireto; 'para' em 'para sempre' é preposição de finalidade e rege adjunto adverbial.",
          "'Sem' em 'sem contar' é preposição que rege oração infinitiva; 'em' em 'em poesia' não existe no trecho, logo está correta a análise de todas as preposições anteriores.",
          "'De' em todas as suas ocorrências (de longe, de coração, de 11 presidentes, de vanguarda, de cotidiano) é preposição que marca origem ou procedência, mantendo invariavelmente essa função.",
          "Todas as preposições do trecho (de, a, para, sem, em) regem necessariamente um complemento verbal ou nominal, sendo impossível identificar preposição como mero modificador adverbial.",
        ],
        correct: 0,
        explanation:
          "Raciocínio didático: 1. Função das preposições: - Preposição liga dois termos, estabelecendo relação de sentido (lugar, tempo, modo, causa, posse, etc.). 2. Análise correta da alternativa A: - 'de longe' → indica modo (como assistiu? de longe) → adjunto adverbial de modo. - 'de coração arfante' → também modo. - 'de 11 presidentes' → liga 'desfile' a 'presidentes' → complemento nominal (desfile de presidentes). 3. Por que as outras alternativas estão incorretas: - B) 'A braço' não aparece no trecho; 'para sempre' é locução adverbial, mas 'para' sozinho não tem essa função. - C) 'Sem contar' – 'sem' rege oração reduzida de infinitivo, mas a afirmação é confusa; além disso, 'em poesia' não existe, mas a alternativa tenta validar análise incorreta. - D) Falsa, pois 'de' pode ter vários valores, não só origem. - E) Falsa, preposições podem formar adjuntos adverbiais sem complemento verbal ou nominal obrigatório. ✅ Resposta: A é a única análise rigorosamente precisa.",
