        statement:
          "Um terminal de cargas em São Luís recebeu um carregamento de 5,75 toneladas de fertilizantes. Esse material deve ser fracionado em recipientes metálicos, cada um com capacidade máxima de 450 quilogramas. Devido às normas de segurança da Marinha, cada recipiente só pode ser preenchido até 4/5 da sua capacidade total para evitar transbordamento durante o içamento. Com base nessas informações, quantos recipientes o operador conseguirá preencher totalmente (dentro do limite de segurança) e quantos quilogramas de fertilizante restarão no lote final?",
