        lessonId: "cfaq-m12",
        statement:
          "Um técnico de suporte trabalha em regime de 36 horas semanais, distribuídas igualmente em 6 dias de trabalho. Em cada um desses dias, ele possui dois intervalos de descanso de 12 minutos cada (tempo que não é contabilizado como hora trabalhada). Considerando apenas o tempo em que o técnico está exercendo suas funções, quantos segundos de trabalho efetivo ele cumpre por dia?",
