        correct: 1,
        explanation:
          "Resposta correta: B.\n\nA carga semanal é de 36 horas distribuídas em 6 dias:\n\n36 ÷ 6 = 6 horas por dia.\n\nEm cada dia há dois intervalos de 12 minutos:\n\n2·12 = 24 minutos.\n\nLogo, o tempo efetivo de trabalho por dia é:\n\n6h − 24min = 5h36min.\n\nConvertendo para minutos:\n\n5h36min = 5·60 + 36 = 336 minutos.\n\nConvertendo para segundos:\n\n336·60 = 20.160 segundos.\n\nAlternativa B.",
