        statement:
          "Durante uma inspeção técnica de rotina em um lote de 60 extintores de incêndio, um inspetor identificou 36 com irregularidades no lacre e 10 com irregularidades simultaneamente no lacre e no manômetro. A quantidade com irregularidades apenas no manômetro era igual à quantidade sem qualquer irregularidade. Com base nessas informações, o número total de extintores que não apresentava defeito no lacre é:",
        options: ["12", "18", "24", "30"],
        correct: 2,
        explanation:
          "Resposta correta: C.\n\nDos 60 extintores, 36 tinham problema no lacre. Desses, 10 tinham problema também no manômetro. Então, apenas com problema no lacre:\n\n36 − 10 = 26.\n\nA quantidade apenas com problema no manômetro é igual à quantidade sem qualquer irregularidade. Chamando cada uma de x:\n\n26 + 10 + x + x = 60\n36 + 2x = 60\n2x = 24\nx = 12.\n\nOs que não apresentam defeito no lacre são os que têm apenas problema no manômetro mais os que não têm defeito algum:\n\n12 + 12 = 24.\n\nAlternativa C.",
